  releaseWrite(error) {
    const callback = this.writeCallback;
    this.writeCallback = undefined;
    callback?.(error);
  }
  releaseFinal() {
    const callback = this.finalCallback;
    this.finalCallback = undefined;
    callback?.();
  }
  _destroy(error, callback) {
    this.destroyCalls += 1;
    callback(error);
  }
