+import { pipeline } from 'node:stream/promises';

 export interface ExportOptions {
   signal?: AbortSignal;
 }

+async function closeOwnedStream(stream: Readable | Writable): Promise<void> {
+  if (stream.closed) return;
+
+  // Also close streams that opted out of automatic destruction. Register first
+  // so synchronous _destroy callbacks cannot race the close observer.
+  const closed = new Promise<void>(resolve => stream.once('close', () => resolve()));
+  stream.destroy();
+  await closed;
+}
+
